"""Finite matrix algebras generated by operator families."""

from __future__ import annotations

from collections.abc import Mapping, Sequence
from dataclasses import dataclass
from typing import Any

import numpy as np

from ..backends import LinearAlgebraBackend, get_backend
from ..certificates import Certificate, Exactness
from ..config import get_settings
from ..exceptions import DimensionError, ValidationError
from ..provenance import ClaimStatus, ProvenanceRecord, documented
from .operators import PacketOperator
from .packets import PacketSystem
from .graphs import TransferGraph
from .seeds import SeedSystem


@dataclass(frozen=True, slots=True)
class AlgebraBasisResult:
    basis: tuple[Any, ...]
    dimension: int
    certificate: Certificate


@documented(
    ProvenanceRecord(
        identifier="PSC-I-D05",
        title="Realized operator algebra",
        status=ClaimStatus.DEFINITION,
        source="Paper I",
        assumptions=("finite matrix generators",),
        verification_suite="core.algebra",
    )
)
class OperatorAlgebra:
    """The unital finite dimensional matrix algebra generated by matrices."""

    def __init__(
        self,
        generators: Mapping[str, Any] | Sequence[Any],
        *,
        backend: str | LinearAlgebraBackend | None = None,
        tolerance: float | None = None,
        include_identity: bool = True,
    ) -> None:
        self.backend = get_backend(backend)
        self.tolerance = get_settings().tolerance if tolerance is None else float(tolerance)
        if isinstance(generators, Mapping):
            items = tuple((str(name), value) for name, value in generators.items())
        else:
            items = tuple((f"A{index}", value) for index, value in enumerate(generators))
        if not items:
            raise ValidationError("an operator algebra requires at least one generator")
        self.generators = {name: self.backend.as_matrix(value) for name, value in items}
        shape = self.backend.shape(next(iter(self.generators.values())))
        if len(shape) != 2 or shape[0] != shape[1]:
            raise DimensionError("operator algebra generators must be square")
        if any(self.backend.shape(value) != shape for value in self.generators.values()):
            raise DimensionError("all operator algebra generators must have one size")
        self.degree = shape[0]
        self.include_identity = bool(include_identity)
        self._basis: tuple[Any, ...] | None = None

    def _flatten(self, matrix: Any) -> Any:
        if self.backend.name == "sympy":
            return matrix.reshape(self.degree * self.degree, 1)
        return np.asarray(matrix).reshape(-1)

    def _rank(self, matrices: list[Any]) -> int:
        if not matrices:
            return 0
        return self.backend.rank(
            self.backend.column_stack([self._flatten(matrix) for matrix in matrices]),
            tolerance=self.tolerance,
        )

    def basis(self) -> tuple[Any, ...]:
        if self._basis is not None:
            return self._basis
        basis: list[Any] = []

        def add(matrix: Any) -> bool:
            candidate = self.backend.as_matrix(matrix)
            if self.backend.is_zero(candidate, tolerance=self.tolerance):
                return False
            old_rank = self._rank(basis)
            new_rank = self._rank([*basis, candidate])
            if new_rank > old_rank:
                basis.append(candidate)
                return True
            return False

        if self.include_identity:
            add(self.backend.eye(self.degree))
        for generator in self.generators.values():
            add(generator)

        changed = True
        while changed and len(basis) < self.degree * self.degree:
            changed = False
            snapshot = tuple(basis)
            for left in snapshot:
                for right in snapshot:
                    if add(self.backend.matmul(left, right)):
                        changed = True
                        if len(basis) == self.degree * self.degree:
                            break
                if len(basis) == self.degree * self.degree:
                    break
        self._basis = tuple(basis)
        return self._basis

    @property
    def dimension(self) -> int:
        return len(self.basis())

    def contains(self, matrix: Any) -> bool:
        value = self.backend.as_matrix(matrix)
        if self.backend.shape(value) != (self.degree, self.degree):
            return False
        basis = list(self.basis())
        return self._rank([*basis, value]) == len(basis)

    def certificate(self) -> Certificate:
        basis = self.basis()
        closed = all(
            self.contains(self.backend.matmul(left, right))
            for left in basis
            for right in basis
        )
        contains_generators = all(self.contains(value) for value in self.generators.values())
        contains_identity = not self.include_identity or self.contains(self.backend.eye(self.degree))
        valid = closed and contains_generators and contains_identity
        return Certificate(
            valid=valid,
            exactness=Exactness.EXACT if self.backend.exact else Exactness.NUMERICAL,
            tolerance=None if self.backend.exact else self.tolerance,
            assumptions_checked=("generator dimensions", "linear independence", "multiplicative closure"),
            diagnostics={
                "degree": self.degree,
                "algebra_dimension": len(basis),
                "maximum_dimension": self.degree * self.degree,
                "backend": self.backend.name,
            },
            theorem_id="PSC-I-D05",
            message="valid generated operator algebra" if valid else "operator algebra closure failed",
        )

    def seed_system(self, seeds: Sequence[Any]) -> SeedSystem:
        return SeedSystem(
            {f"B{index}": matrix for index, matrix in enumerate(self.basis())},
            seeds,
            backend=self.backend,
            tolerance=self.tolerance,
        )

    def transfer_graph(self, packets: PacketSystem) -> TransferGraph:
        if packets.backend.name != self.backend.name or packets.dimension != self.degree:
            raise DimensionError("packet system does not match the operator algebra")
        family = [PacketOperator.from_operator(matrix, packets) for matrix in self.generators.values()]
        return TransferGraph.from_operator_family(family, tolerance=self.tolerance)


def matrix_units(size: int, *, backend: str | LinearAlgebraBackend | None = None) -> tuple[Any, ...]:
    """Return the standard matrix units of the requested square size."""

    if size < 1:
        raise ValueError("size must be positive")
    active = get_backend(backend)
    units: list[Any] = []
    for row in range(size):
        for column in range(size):
            matrix = active.zeros(size, size)
            matrix[row, column] = 1
            units.append(matrix)
    return tuple(units)
